-- ---------------------------------------------------------------------------------------------
-- 2. users.id is auth.users.id (Supabase Auth owns identity; Atarah owns the profile of the account)
-- ---------------------------------------------------------------------------------------------
ALTER TABLE "users"
  ADD CONSTRAINT "users_id_auth_users_fkey" FOREIGN KEY ("id") REFERENCES auth.users ("id") ON DELETE CASCADE;

-- A new auth user becomes a PENDING_VERIFICATION (or ACTIVE when already confirmed) account, with the consent
-- the app sent at sign-up. user_metadata supplies display text and consent versions only, never roles or status.
CREATE OR REPLACE FUNCTION public.handle_auth_user_created() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE
  v_phone text := CASE WHEN COALESCE(NEW.phone, '') = '' THEN NULL ELSE '+' || ltrim(NEW.phone, '+') END;
  v_email text := NULLIF(NEW.email, '');
  v_name  text := COALESCE(NULLIF(btrim(NEW.raw_user_meta_data ->> 'full_name'), ''), 'Atarah member');
  v_confirmed boolean := NEW.email_confirmed_at IS NOT NULL OR NEW.phone_confirmed_at IS NOT NULL;
BEGIN
  INSERT INTO public.users (
    "id", "email", "phone", "emailVerifiedAt", "phoneVerifiedAt", "fullName", "status", "statusChangedAt",
    "createdAt", "updatedAt"
  ) VALUES (
    NEW.id, v_email, v_phone,
    NEW.email_confirmed_at AT TIME ZONE 'UTC', NEW.phone_confirmed_at AT TIME ZONE 'UTC',
    left(v_name, 120),
    (CASE WHEN v_confirmed THEN 'ACTIVE' ELSE 'PENDING_VERIFICATION' END)::"AccountStatus",
    CASE WHEN v_confirmed THEN (now() AT TIME ZONE 'UTC') ELSE NULL END,
    now() AT TIME ZONE 'UTC', now() AT TIME ZONE 'UTC'
  ) ON CONFLICT ("id") DO NOTHING;

  IF COALESCE(NEW.raw_user_meta_data ->> 'terms_version', '') <> '' THEN
    INSERT INTO public.consent_records ("id", "userId", "documentType", "version", "acceptedAt", "source", "createdAt", "updatedAt")
    VALUES (gen_random_uuid(), NEW.id, 'TERMS', left(NEW.raw_user_meta_data ->> 'terms_version', 40),
            now() AT TIME ZONE 'UTC', 'signup', now() AT TIME ZONE 'UTC', now() AT TIME ZONE 'UTC');
  END IF;
  IF COALESCE(NEW.raw_user_meta_data ->> 'privacy_version', '') <> '' THEN
    INSERT INTO public.consent_records ("id", "userId", "documentType", "version", "acceptedAt", "source", "createdAt", "updatedAt")
    VALUES (gen_random_uuid(), NEW.id, 'PRIVACY', left(NEW.raw_user_meta_data ->> 'privacy_version', 40),
            now() AT TIME ZONE 'UTC', 'signup', now() AT TIME ZONE 'UTC', now() AT TIME ZONE 'UTC');
  END IF;
  RETURN NEW;
END $$;

-- Keeps contact details, verification flags and the first activation in step with Supabase Auth.
CREATE OR REPLACE FUNCTION public.handle_auth_user_updated() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE
  v_phone text := CASE WHEN COALESCE(NEW.phone, '') = '' THEN NULL ELSE '+' || ltrim(NEW.phone, '+') END;
  v_confirmed boolean := NEW.email_confirmed_at IS NOT NULL OR NEW.phone_confirmed_at IS NOT NULL;
BEGIN
  UPDATE public.users u SET
    "email" = NULLIF(NEW.email, ''),
    "phone" = v_phone,
    "emailVerifiedAt" = NEW.email_confirmed_at AT TIME ZONE 'UTC',
    "phoneVerifiedAt" = NEW.phone_confirmed_at AT TIME ZONE 'UTC',
    "lastLoginAt" = COALESCE(NEW.last_sign_in_at AT TIME ZONE 'UTC', u."lastLoginAt"),
    "status" = CASE WHEN u."status" = 'PENDING_VERIFICATION' AND v_confirmed
                    THEN 'ACTIVE'::"AccountStatus" ELSE u."status" END,
    "statusChangedAt" = CASE WHEN u."status" = 'PENDING_VERIFICATION' AND v_confirmed
                             THEN now() AT TIME ZONE 'UTC' ELSE u."statusChangedAt" END,
    "updatedAt" = now() AT TIME ZONE 'UTC'
  WHERE u."id" = NEW.id;
  RETURN NEW;
END $$;

CREATE TRIGGER atarah_on_auth_user_created AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE FUNCTION public.handle_auth_user_created();
CREATE TRIGGER atarah_on_auth_user_updated
  AFTER UPDATE OF email, phone, email_confirmed_at, phone_confirmed_at, last_sign_in_at ON auth.users
  FOR EACH ROW EXECUTE FUNCTION public.handle_auth_user_updated();

REVOKE ALL ON FUNCTION public.handle_auth_user_created() FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.handle_auth_user_updated() FROM PUBLIC, anon, authenticated;

-- ---------------------------------------------------------------------------------------------
-- 3. Row Level Security on every table: deny all for anon and authenticated (no policies), except the one
--    notifications SELECT policy that Realtime needs (Master Prompt 5.7, rules 2 and 4).
-- ---------------------------------------------------------------------------------------------
DO $$
DECLARE t record;
BEGIN
  FOR t IN SELECT tablename FROM pg_tables WHERE schemaname = 'public' LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t.tablename);
  END LOOP;
END $$;

REVOKE ALL ON ALL TABLES IN SCHEMA public FROM anon, authenticated;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM anon, authenticated;
ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON TABLES FROM anon, authenticated;
ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON SEQUENCES FROM anon, authenticated;
ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON FUNCTIONS FROM anon, authenticated;

GRANT SELECT ON public.notifications TO authenticated;
CREATE POLICY notifications_select_own ON public.notifications
  FOR SELECT TO authenticated USING ("userId" = auth.uid());

-- ---------------------------------------------------------------------------------------------
-- 4. Realtime: only notifications is published.
-- ---------------------------------------------------------------------------------------------
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_publication WHERE pubname = 'supabase_realtime') THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.notifications;
  END IF;
END $$;

-- ---------------------------------------------------------------------------------------------
-- 5. The backend database role: separate from anon/authenticated, bypasses RLS. Its password is set by
--    scripts/provision-backend-role.mjs from the secret store, never in a migration.
-- ---------------------------------------------------------------------------------------------
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'atarah_backend') THEN
    CREATE ROLE atarah_backend LOGIN BYPASSRLS NOINHERIT;
  END IF;
END $$;

ALTER ROLE atarah_backend SET search_path = public, extensions;
GRANT USAGE ON SCHEMA public TO atarah_backend;
GRANT ALL ON ALL TABLES IN SCHEMA public TO atarah_backend;
GRANT ALL ON ALL SEQUENCES IN SCHEMA public TO atarah_backend;
GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA public TO atarah_backend;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON TABLES TO atarah_backend;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON SEQUENCES TO atarah_backend;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT EXECUTE ON FUNCTIONS TO atarah_backend;

-- The backend never gets direct access to the Supabase-managed `auth` schema. The few things it needs (the
-- Active sessions list, revoking a session, the MFA factor summary and the "is this session still live" check
-- in the auth guard) go through narrow SECURITY DEFINER functions owned by postgres, executable only by the
-- backend role.
CREATE FUNCTION public.atarah_auth_session_exists(p_session uuid, p_user uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_temp AS $$
  SELECT EXISTS (SELECT 1 FROM auth.sessions WHERE id = p_session AND user_id = p_user)
$$;

CREATE FUNCTION public.atarah_auth_list_sessions(p_user uuid)
RETURNS TABLE (id uuid, created_at timestamptz, updated_at timestamptz)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_temp AS $$
  SELECT s.id, s.created_at, s.updated_at FROM auth.sessions s WHERE s.user_id = p_user
  ORDER BY COALESCE(s.updated_at, s.created_at) DESC LIMIT 50
$$;

CREATE FUNCTION public.atarah_auth_delete_session(p_session uuid, p_user uuid) RETURNS integer
LANGUAGE sql SECURITY DEFINER SET search_path = pg_temp AS $$
  WITH d AS (DELETE FROM auth.sessions WHERE id = p_session AND user_id = p_user RETURNING 1)
  SELECT count(*)::int FROM d
$$;

CREATE FUNCTION public.atarah_auth_delete_user_sessions(p_user uuid, p_except uuid DEFAULT NULL) RETURNS integer
LANGUAGE sql SECURITY DEFINER SET search_path = pg_temp AS $$
  WITH d AS (DELETE FROM auth.sessions WHERE user_id = p_user AND (p_except IS NULL OR id <> p_except) RETURNING 1)
  SELECT count(*)::int FROM d
$$;

CREATE FUNCTION public.atarah_auth_count_sessions(p_user uuid) RETURNS integer
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_temp AS $$
  SELECT count(*)::int FROM auth.sessions WHERE user_id = p_user
$$;

CREATE FUNCTION public.atarah_auth_list_mfa_factors(p_user uuid)
RETURNS TABLE (id uuid, factor_type text, status text, friendly_name text, created_at timestamptz)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_temp AS $$
  SELECT f.id, f.factor_type::text, f.status::text, f.friendly_name, f.created_at
  FROM auth.mfa_factors f WHERE f.user_id = p_user ORDER BY f.created_at
$$;

REVOKE ALL ON FUNCTION public.atarah_auth_session_exists(uuid, uuid),
  public.atarah_auth_list_sessions(uuid), public.atarah_auth_delete_session(uuid, uuid),
  public.atarah_auth_delete_user_sessions(uuid, uuid), public.atarah_auth_count_sessions(uuid),
  public.atarah_auth_list_mfa_factors(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.atarah_auth_session_exists(uuid, uuid),
  public.atarah_auth_list_sessions(uuid), public.atarah_auth_delete_session(uuid, uuid),
  public.atarah_auth_delete_user_sessions(uuid, uuid), public.atarah_auth_count_sessions(uuid),
  public.atarah_auth_list_mfa_factors(uuid) TO atarah_backend;
